scripts.何梅对话.txt:
// 与同伴何梅的对话

	If ($Talkmap016hemei == 0) @Talk0;
	If ($Talkmap016hemei == 1) @Talk1;
	If ($Talkmap016hemei == 2) @Talk2;
	If ($Talkmap016hemei == 3) @Talk3;
	Return;
@Talk0:	
	Say("何梅：独孤公子是哪里人？", 66);
	Say("独孤剑：我自幼父母双亡，被师傅带回衡山抚育成人。", 1);
	Assign($Talkmap016hemei, 1);
	Return;
@Talk1:	
	Say("何梅：独孤公子可有兄弟姊妹？", 66);
	Say("独孤剑：我有许多同门学艺的师弟师妹。", 1);
	Assign($Talkmap016hemei, 2);
	Return;
@Talk2:	
	Say("何梅（害羞的）：独孤公子是否……是否已成家立室？", 66);
	Say("独孤剑：我乃一江湖草莽之人，过着一种刀光剑影、四处飘摇的生活，寻常女子怎愿与我相伴？况且我也不想误人青春。", 1);
	Say("何梅：……", 66);
	Assign($Talkmap016hemei, 3);
	Return;
@Talk3:	
	Say("独孤剑：何姑娘家住哪里？", 1);
	Say("何梅：我家住在城北，就在官衙的后面。", 66);
	Return;

scripts.段铁匠对话.txt:
// 与段铁匠的对话

	If ($Talkmap025duan == 0) @Talk0;
	If ($Talkmap025duan == 1) @Talk1;
		
@Talk0:
	Say("段铁匠：小伙子，你是干什么来的？", 0);
	Say("段铁匠：你若是来打我宝贝女儿的主意，最好趁我没有生气之前赶快走开。", 0);
	Say("独孤剑：不是，随便看看，看看您打的剑怎么样。", 2);
	Assign($Talkmap025duan, 1);
	Return;
	
@Talk1:
	Say("段铁匠：年纪轻轻的，不去学点手艺养家糊口，只知道东颠西跑好玩，现在的年轻人啦……", 0);
	Return;

scripts.贾老实对话.txt:
// 与贾老实的同伴对话

	If($Event == 120) @Event120;
	Return;
	
@Event120:
	If($Talkmap025jia == 0) @Talk0;
	If($Talkmap025jia == 1) @Talk1;
	If($Talkmap025jia == 2) @Talk2;
	Return;
	
@Talk0:
	Say("贾老实：京城是个花花世界，如果不是因为金兵南下，这里以前更热闹。", 207);
	Assign($Talkmap025jia, 1);
	Return;	
@Talk1:
	Say("贾老实：人生在世，不就是图个吃喝玩乐，老弟，你说呢？", 207);
	Say("独孤剑：如果只顾自己享乐，而置国家安危于不顾，有朝一日金兵南侵，攻破城池，覆巢之下，安有完卵？", 1);
	Say("贾老实：哪里管得了那许多！", 207);
	Say("独孤剑：人人都像你这样想，大宋迟早要亡国。", 1);
	Assign($Talkmap025jia, 2);
	Return;
@Talk2:
	Say("贾老实：我最关心的就是赚钱，别的我可不想管。", 207);
	Say("独孤剑：……", 1);
	Return;

scripts.铁匠学徒对话.txt:
// 与铁匠学徒的对话

	CheckYear($Value);  
	If ($Value == 0) @NotYuanDan;	
	If ($Value == 1) @YuanDan;	
	
@NotYuanDan:

	Say("徒弟（悄悄地）：告诉你，师傅的女儿芙蓉姐姐好漂亮耶，而且她还会变相，一下子就可以变得你认不出来。可惜你来的不是时候，她出门去了。你没这个眼福，怪不得别人喔。", 0);
	Say("徒弟：你要买点什么？我们这里打造的兵刃全京城都很有名的喔！", 0);

	GetPlayerLevel($PlayerLevel);
	If ($PlayerLevel << 10) @PlayerLevelL10;
	If ($PlayerLevel << 16) @PlayerLevelL16;
	If ($PlayerLevel << 22) @PlayerLevelL22;
	If ($PlayerLevel << 28) @PlayerLevelL28;
	If ($PlayerLevel << 34) @PlayerLevelL34;
	If ($PlayerLevel << 40) @PlayerLevelL40;
	Goto @PlayerLevelG40;
	Goto @BuyEnd;

@PlayerLevelL10:
	SellGoods("buy1级武器.ini");
	Goto @BuyEnd;
@PlayerLevelL16:
	SellGoods("buy2级武器.ini");
	Goto @BuyEnd;
@PlayerLevelL22:
	SellGoods("buy3级武器.ini");
	Goto @BuyEnd;
@PlayerLevelL28:
	SellGoods("buy4级武器.ini");
	Goto @BuyEnd;
@PlayerLevelL34:
	SellGoods("buy5级武器.ini");
	Goto @BuyEnd;
@PlayerLevelL40:
	SellGoods("buy6级武器.ini");
	Goto @BuyEnd;
@PlayerLevelG40:
	SellGoods("buy7级武器.ini");
	Goto @BuyEnd;
@BuyEnd:

	If($Bixue == 0) @Bixue0;
	If($Bixue == 1) @Bixue1;		
@Bixue0:
	Sleep(600);
	Say("徒弟：前些日子我师父得了一把宝刀，叫做碧潮宝刃，锋锐异常，就是价格比较贵，要两千五百两银子，你买不买？", 0);	
	Choose("独孤剑：我……","A 不买","B 买",$Choose);
	If ($Choose == 0) @Choose0;
	If ($Choose == 1) @Choose1;
	
@Choose0:
	Say("独孤剑：多谢，在下暂时不需要。",1);
	Return;
	
@Choose1:
	GetMoneyNum();
	If($MoneyNum << 2500) @NotenoughMon;
	If($MoneyNum >= 2500) @EnoughMon;
@NotenoughMon:
	Say("独孤剑：哎呀，银子不够了。", 9);
	Say("徒弟：这可是一把好刀，你凑够了银子再来吧。", 86);
	Return;
@EnoughMon:
	Say("独孤剑：好，我买了。", 1);
	AddMoney(-2500);
	AddGoods("Goods051_碧潮宝刃.ini");
	Assign($Bixue, 1);
	Return;
@Bixue1:
	Return;	
	
	
@YuanDan:		
	
	Say("徒弟：恭喜发财！", 0);
	Say("徒弟（悄悄地）：告诉你，师傅的女儿芙蓉姐姐好漂亮耶，而且她还会变相，一下子就可以变得你认不出来。可惜你来的不是时候，她出门去了。你没这个眼福，怪不得别人喔。", 0);
	Say("徒弟：你要买点什么？我们这里打造的兵刃全京城都很有名的喔！为迎接新年，今天我们这里所有的兵刃都半价销售！", 0);

	GetPlayerLevel($PlayerLevel);
	If ($PlayerLevel << 10) @PlayerLevelL10YD;
	If ($PlayerLevel << 16) @PlayerLevelL16YD;
	If ($PlayerLevel << 22) @PlayerLevelL22YD;
	If ($PlayerLevel << 28) @PlayerLevelL28YD;
	If ($PlayerLevel << 34) @PlayerLevelL34YD;
	If ($PlayerLevel << 40) @PlayerLevelL40YD;
	Goto @PlayerLevelG40YD;
	Goto @BuyEndYD;

@PlayerLevelL10YD:
	SellGoods("buy过年1级武器.ini");
	Goto @BuyEndYD;
@PlayerLevelL16YD:
	SellGoods("buy过年2级武器.ini");
	Goto @BuyEndYD;
@PlayerLevelL22YD:
	SellGoods("buy过年3级武器.ini");
	Goto @BuyEndYD;
@PlayerLevelL28YD:
	SellGoods("buy过年4级武器.ini");
	Goto @BuyEndYD;
@PlayerLevelL34YD:
	SellGoods("buy过年5级武器.ini");
	Goto @BuyEndYD;
@PlayerLevelL40YD:
	SellGoods("buy过年6级武器.ini");
	Goto @BuyEndYD;
@PlayerLevelG40YD:
	SellGoods("buy过年7级武器.ini");
	Goto @BuyEndYD;
@BuyEndYD:

	If($Bixue == 0) @Bixue0YD;
	If($Bixue == 1) @Bixue1YD;		
@Bixue0YD:
	Sleep(600);
	Say("徒弟：前些日子我师父得了一把宝刀，叫做碧潮宝刃，锋锐异常，就是价格比较贵，要两千五百两银子，你买不买？", 0);	
	Choose("独孤剑：我……","A 不买","B 买",$Choose);
	If ($Choose == 0) @Choose0YD;
	If ($Choose == 1) @Choose1YD;
	
@Choose0YD:
	Say("独孤剑：多谢，在下暂时不需要。",1);
	Return;
	
@Choose1YD:
	GetMoneyNum();
	If($MoneyNum << 2500) @NotenoughMon;
	If($MoneyNum >= 2500) @EnoughMon;
@NotenoughMon:
	Say("独孤剑：哎呀，银子不够了。", 9);
	Say("徒弟：这可是一把好刀，你凑够了银子再来吧。", 86);
	Return;
@EnoughMon:
	Say("独孤剑：好，我买了。", 1);
	AddMoney(-2500);
	AddGoods("Goods051_碧潮宝刃.ini");
	Assign($Bixue, 1);
	Return;
	
	
@Bixue1YD:
	Return;

